INSERT INTO quizzes (lesson_id, question, options, correct_answer, explanation) VALUES
('f6000000-0000-0000-0000-000000000001', 'O que o PIB mede?', '["O bem-estar da população","A soma de bens e serviços produzidos","A riqueza total acumulada","O nível de emprego"]', 1, 'O PIB mede a soma de todos os bens e serviços finais produzidos em um país durante um período.'),
('f6000000-0000-0000-0000-000000000001', 'Quem criou o conceito moderno de PIB?', '["Adam Smith","John Keynes","Simon Kuznets","Milton Friedman"]', 2, 'Simon Kuznets, Nobel de Economia, desenvolveu o conceito moderno de PIB em 1934.'),
('f6000000-0000-0000-0000-000000000001', 'Qual órgão define a taxa Selic no Brasil?', '["CVM","IBGE","Copom","Receita Federal"]', 2, 'O Copom (Comitê de Política Monetária) do Banco Central define a Selic a cada 45 dias.'),
('f6000000-0000-0000-0000-000000000002', 'O que fortalece uma moeda nacional?', '["Alta inflação","Juros altos atraindo capital estrangeiro","Déficit comercial","Instabilidade política"]', 1, 'Juros altos atraem capital estrangeiro, aumentando a demanda pela moeda e fortalecendo-a.'),
('f6000000-0000-0000-0000-000000000002', 'Quem quebrou o Banco da Inglaterra em 1992?', '["Warren Buffett","Ray Dalio","George Soros","Carl Icahn"]', 2, 'George Soros apostou contra a libra esterlina e lucrou US$ 1 bilhão em um dia.'),
('f6000000-0000-0000-0000-000000000003', 'O que é o Momento Minsky?', '["Quando a economia cresce rápido","Quando estabilidade leva a excesso de risco e crise","Quando juros sobem","Quando o PIB cai"]', 1, 'Hyman Minsky demonstrou que períodos prolongados de estabilidade encorajam risco excessivo, gerando crises.'),
('f6000000-0000-0000-0000-000000000003', 'Qual frase é considerada a mais perigosa em finanças?', '["Compre na baixa","Desta vez é diferente","O mercado sempre sobe","Diversifique sempre"]', 1, 'Reinhart e Rogoff mostraram que a frase "desta vez é diferente" precede muitas crises financeiras.'),
('f6000000-0000-0000-0000-000000000004', 'O que é a Teoria da Perspectiva de Kahneman?', '["Mercados são eficientes","Pessoas avaliam ganhos e perdas assimetricamente","Inflação é monetária","Diversificação elimina risco"]', 1, 'Kahneman mostrou que a dor de perder R$ 100 é 2x maior que a alegria de ganhar R$ 100.'),
('f6000000-0000-0000-0000-000000000004', 'O que é um nudge segundo Richard Thaler?', '["Um imposto","Uma mudança sutil no ambiente de decisão","Uma multa","Um incentivo financeiro"]', 1, 'Nudge é uma pequena mudança no ambiente que influencia comportamentos sem restringir liberdade.'),
('f6000000-0000-0000-0000-000000000005', 'Qual é a Regra dos 4% para aposentadoria?', '["Investir 4% da renda","Retirar 4% ao ano do patrimônio","Poupar por 4 anos","Ter 4% em renda fixa"]', 1, 'William Bengen demonstrou que retirar 4% ao ano de uma carteira diversificada é sustentável por 30+ anos.'),
('f6000000-0000-0000-0000-000000000005', 'O que é o gap previdenciário?', '["Diferença entre INSS e salário atual","Tempo até aposentadoria","Taxa do INSS","Valor da contribuição"]', 0, 'O gap previdenciário é a diferença entre o teto do INSS e a renda que você precisa na aposentadoria.'),
